/* Glossary: 405 terms.  c category, n name, p plain-English, u where you meet it */
window.GLOSSARY = [{"c":"Architecture","n":"Abstraction","p":"Hide detail behind a simpler concept/interface.","u":"Functions, APIs, ORMs, frameworks; bad abstractions hide the wrong things."},{"c":"Security","n":"Access Control","p":"Deciding which identities may perform which actions on which records.","u":"Check on every request, on the server."},{"c":"Frontend","n":"Accessibility","p":"Making a product usable by people with disabilities.","u":"Semantic elements, labels, alt text, contrast and keyboard support."},{"c":"Frontend","n":"Accessibility (a11y)","p":"Design/code that lets people use software with keyboards, screen readers, zoom, different abilities.","u":"Semantic HTML, focus, labels, contrast, ARIA when necessary."},{"c":"Database","n":"ACID","p":"Common properties describing reliable transaction behavior: atomicity, consistency, isolation, durability.","u":"Mental model for why transactions protect multi-step writes."},{"c":"Database","n":"Aggregate","p":"A function collapsing many rows into one value: COUNT, SUM, AVG, MIN, MAX.","u":"The basis of every report."},{"c":"AI Coding","n":"AI review loop","p":"Plan → inspect → edit → run tests → inspect diff → verify behavior.","u":"Treat generated code as a proposal until evidence proves it."},{"c":"DevOps","n":"Alert","p":"Automated notification triggered by a condition indicating possible user/system impact.","u":"Error rate, availability, queue backlog; avoid alerting on noise."},{"c":"DevOps","n":"Alerting","p":"Notifying a human when a measured signal crosses a threshold.","u":"Alert on symptoms users feel, and give every alert an action."},{"c":"Core","n":"Algorithm","p":"A defined procedure for turning input into output.","u":"Sorting, searching, scheduling, matching, optimization."},{"c":"Frontend","n":"Alignment","p":"Positioning items along or across a layout axis.","u":"justify-content along the main axis, align-items across it."},{"c":"Frontend","n":"Alt Text","p":"A short text description of an image, read aloud by screen readers.","u":"Required for meaningful images; use alt=\"\" for decorative ones."},{"c":"Backend","n":"API","p":"A defined interface through which software asks other software for data/actions.","u":"Frontend↔backend, third-party services, libraries."},{"c":"Core","n":"Argument","p":"The actual value supplied when calling a function.","u":"Debug function inputs when outputs look wrong."},{"c":"Frontend","n":"ARIA","p":"Attributes that describe roles and states to assistive technology.","u":"Use a real semantic element first; ARIA is the fallback."},{"c":"Core","n":"Array","p":"A fixed-length, ordered run of values reached by numeric position starting at 0.","u":"Fast to index, awkward to resize."},{"c":"Core","n":"Array / list","p":"An ordered collection of values.","u":"Rows returned from APIs, UI lists, queues, batches."},{"c":"Language","n":"ArrayList","p":"Java's resizable list, backed by an array that grows as needed.","u":"Use .add(), .get(i) and .size()."},{"c":"DevOps","n":"Artifact","p":"Output produced by a build for deployment/distribution.","u":"Container image, compiled bundle, package."},{"c":"Testing","n":"Assertion","p":"Statement in a test that declares expected behavior/value.","u":"Test failures point to violated expectations."},{"c":"Language","n":"async / await","p":"Syntax for writing promise-based asynchronous code in a sequential-looking style.","u":"API calls, database calls, background operations."},{"c":"Language","n":"Asynchronous","p":"Work starts now and completion is handled later without blocking the same execution path.","u":"Network requests, timers, file I/O, database calls."},{"c":"Security","n":"Audit","p":"Reviewing code, dependencies or access for security problems.","u":"npm audit, dependency scanning, and access reviews."},{"c":"Security","n":"Authentication","p":"Proving an identity.","u":"Login, session creation, identity provider."},{"c":"Security","n":"Authorization","p":"Deciding whether an identity may perform a particular action on a particular resource.","u":"Tenant isolation, admin permissions, record ownership."},{"c":"Java","n":"Autoboxing","p":"Automatic conversion between a primitive (int) and its object wrapper (Integer).","u":"Convenient, but a null Integer unboxed to int throws."},{"c":"Backend","n":"Background job","p":"Work handled outside the interactive request path.","u":"Emails, exports, imports, image processing."},{"c":"DevOps","n":"Backup","p":"Separate recoverable copy of important data.","u":"Disaster recovery; a backup you never tested restoring is only a hope."},{"c":"Security","n":"bcrypt","p":"A deliberately slow password-hashing algorithm with a tunable cost.","u":"Slowness is the feature; it makes mass cracking expensive."},{"c":"Core","n":"Big O","p":"A way to describe how work/memory grows as input size grows.","u":"Useful when a design works for 100 items but struggles at 1,000,000."},{"c":"AI Coding","n":"Blast radius","p":"How much of the system could be affected by one change.","u":"Ask agents for smallest viable diff and list touched boundaries."},{"c":"DevOps","n":"Blue/green deployment","p":"Run old and new production versions separately then switch traffic.","u":"Lower-risk releases/fast rollback at higher infrastructure cost."},{"c":"Core","n":"Boolean","p":"A true/false value.","u":"Flags such as isAdmin, isLoading, hasPaid."},{"c":"Frontend","n":"Border","p":"The line drawn between an element's padding and its margin.","u":"Counts toward width unless box-sizing is border-box."},{"c":"Frontend","n":"Box Model","p":"Content, padding, border and margin, from the inside out.","u":"Explains why a 300px box can occupy 340px."},{"c":"Git","n":"Branch","p":"Movable name pointing to a line of commits.","u":"Parallel feature/fix work."},{"c":"Security","n":"Broken access control","p":"System fails to enforce what authenticated users are allowed to access/do.","u":"Object ownership, admin routes, multi-tenant systems; major web-app risk category."},{"c":"Frontend","n":"Bubbling","p":"An event travelling up from the element it happened on through its ancestors.","u":"Lets one listener on a parent handle many children."},{"c":"DevOps","n":"Build","p":"Process that turns source + dependencies/config into runnable/deployable output.","u":"Compile TypeScript, bundle frontend, generate assets."},{"c":"DevOps","n":"Build Tool","p":"Software that automates compiling, bundling and packaging a project.","u":"make, Gradle, Maven, Vite."},{"c":"Frontend","n":"Bundler","p":"Tool that processes/modules/transforms assets into browser-deployable output.","u":"Vite, webpack, Rollup, esbuild-based workflows."},{"c":"Backend","n":"Business logic","p":"Rules that describe what your product is allowed to do.","u":"Pricing, status transitions, ownership rules, scheduling."},{"c":"Java","n":"Bytecode","p":"The intermediate instruction set Java compiles to, stored in .class files.","u":"Compiled once by javac, executed by the JVM."},{"c":"Architecture","n":"Cache","p":"Stored reusable result used to avoid repeated expensive work.","u":"Browser, CDN, Redis, server memory, DB pages."},{"c":"Core","n":"Call stack","p":"The runtime stack of active function calls.","u":"Stack traces show this path when code crashes."},{"c":"Language","n":"Callback","p":"A function passed somewhere so it can be called later.","u":"Events, array methods, older async APIs."},{"c":"DevOps","n":"Canary release","p":"Send a small portion of traffic/users to a new version before broader rollout.","u":"Detect production issues with limited blast radius."},{"c":"Frontend","n":"Cascade","p":"The rules deciding which CSS declaration wins when several apply.","u":"Origin, then specificity, then source order."},{"c":"DevOps","n":"CD","p":"Continuous Delivery/Deployment: automating release readiness or actual deployment.","u":"Repeatable production shipping."},{"c":"Network","n":"CDN","p":"Distributed network that serves/cache content closer to users.","u":"Static assets, edge caching, protection."},{"c":"Network","n":"Certificate","p":"A signed document proving a server owns the domain it claims.","u":"What makes the padlock appear, and what TLS verifies."},{"c":"Java","n":"Checked Exception","p":"An exception the compiler forces you to catch or declare.","u":"Unique to Java, and the reason for throws clauses."},{"c":"DevOps","n":"CI","p":"Continuous Integration: automated checks/build/tests triggered by code changes.","u":"Pull requests and main branch quality gates."},{"c":"DevOps","n":"CI/CD","p":"Automation that tests every change and ships the ones that pass.","u":"Removes the steps a tired human would skip."},{"c":"Language","n":"Class","p":"A blueprint-like construct combining data and behavior in object-oriented languages.","u":"Models/services/framework code; not required for every design."},{"c":"Network","n":"Client Error","p":"A 4xx status meaning the request itself was wrong.","u":"Fix the caller, not the server."},{"c":"Frontend","n":"Client-side rendering (CSR)","p":"Browser JavaScript creates/updates much of the page after loading.","u":"Single-page applications and interactive dashboards."},{"c":"Core","n":"Closure","p":"A function that retains access to variables from the scope where it was created.","u":"Callbacks, event handlers, factories, React hooks, and stale-value bugs."},{"c":"AI Coding","n":"Coding agent","p":"AI system that can inspect/edit/run code across a repository.","u":"Fast implementation, refactors, debugging. Best when given narrow goals and verification criteria."},{"c":"Architecture","n":"Cohesion","p":"How strongly responsibilities inside a module belong together.","u":"High cohesion usually makes modules easier to understand."},{"c":"DevOps","n":"Cold Start","p":"The delay when a serverless function has to boot before handling a request.","u":"The main trade-off of scaling to zero."},{"c":"Language","n":"Collection","p":"A container holding many values: a list, set, map or similar.","u":"Choosing the right one often removes a loop."},{"c":"Database","n":"Column","p":"Named attribute with a type/constraint in a table.","u":"email, created_at, status."},{"c":"Git","n":"Commit","p":"Named snapshot of project history plus metadata/parent link.","u":"Checkpoints, review, rollback/revert, blame/history."},{"c":"Language","n":"Compiler","p":"Transforms source code into another form, often machine code or lower-level output.","u":"TypeScript→JavaScript, C/Rust→machine code, build systems."},{"c":"Frontend","n":"Component","p":"A reusable UI unit that owns a chunk of rendering/behavior.","u":"React/Vue/Svelte and design systems."},{"c":"Language","n":"Composition","p":"Build behavior by combining smaller parts instead of inheriting a hierarchy.","u":"Components, services, functions, middleware pipelines."},{"c":"Core","n":"Concatenation","p":"Joining two strings end to end to make a new one.","u":"\"Hi \" + name."},{"c":"Language","n":"Concurrency","p":"Making progress on multiple tasks during overlapping time.","u":"Servers handling many requests, async I/O, workers."},{"c":"Core","n":"Conditional","p":"A branch that runs code only when a condition is true/false.","u":"Permissions, form validation, feature flags, status logic."},{"c":"Backend","n":"Configuration","p":"Settings that differ between environments but not in the code.","u":"Database URLs, keys, log levels and feature flags."},{"c":"Git","n":"Conflict","p":"Two branches changing the same lines, so Git asks you to choose.","u":"Not an error, just a decision it will not make for you."},{"c":"Database","n":"Connection pool","p":"Reusable set of database connections shared by application work.","u":"Avoids opening a fresh expensive connection for every query and controls concurrency."},{"c":"C++","n":"Const Correctness","p":"Marking anything that should not change as const so the compiler enforces it.","u":"Turns a class of bugs into compile errors."},{"c":"Core","n":"Constant","p":"A binding you do not intend to reassign after creation.","u":"Use it by default when a name should keep referring to the same value."},{"c":"Core","n":"Constructor","p":"The function that runs when an object is created, setting its starting state.","u":"Shares the class name and has no return type."},{"c":"DevOps","n":"Container","p":"Isolated process packaging model bundling app + filesystem/dependencies with controlled runtime config.","u":"Docker-based deploys and reproducible environments."},{"c":"DevOps","n":"Container image","p":"Immutable-ish template used to start containers.","u":"Built in CI, stored in registry, deployed to runtime."},{"c":"AI Coding","n":"Context window","p":"Amount of information an AI model can actively consider in one interaction.","u":"Large repos exceed it; repo maps, targeted files, and clear constraints improve reliability."},{"c":"Network","n":"Contract","p":"The agreed shape of the data two systems exchange.","u":"Which fields exist, what type each is, and which may be absent."},{"c":"Core","n":"Control flow","p":"The order in which instructions actually execute.","u":"Core to reading code and isolating wrong branches/returns."},{"c":"Frontend","n":"Controlled input","p":"Form value is driven by application state.","u":"React forms, validation, dynamic inputs."},{"c":"Frontend","n":"Cookie","p":"Small browser-stored data automatically associated with requests under configured rules.","u":"Sessions, preferences, security attributes such as HttpOnly/SameSite/Secure."},{"c":"Network","n":"CORS","p":"Browser policy controlling whether one origin may read resources from another origin.","u":"Separate frontend/API domains during dev/prod."},{"c":"Architecture","n":"Coupling","p":"How strongly one module depends on details of another.","u":"High coupling makes changes ripple farther."},{"c":"Backend","n":"Cron job","p":"A scheduled task triggered by time rather than a user request.","u":"Daily summaries, cleanup, billing cycles."},{"c":"Backend","n":"CRUD","p":"Create, Read, Update, Delete: the basic lifecycle of stored records.","u":"Admin panels, forms, data APIs."},{"c":"Security","n":"CSRF","p":"Cross-site request forgery: attacker causes a victim's browser to send an authenticated state-changing request.","u":"SameSite cookies, CSRF tokens, origin checks depending architecture."},{"c":"Frontend","n":"CSS","p":"Rules controlling presentation and layout of web content.","u":"Responsive layout, typography, spacing, animation, themes."},{"c":"Frontend","n":"CSS Grid","p":"Two-dimensional CSS layout, rows and columns together.","u":"Page-level layouts and card grids that reflow."},{"c":"C++","n":"Dangling Pointer","p":"A pointer to memory that has already been freed.","u":"Reading it gives whatever happens to be there now, which may look valid."},{"c":"Core","n":"Data structure","p":"A way to organize data for particular operations/tradeoffs.","u":"Arrays, maps, sets, trees, queues, heaps, graphs."},{"c":"Core","n":"Data type","p":"A category of value with specific operations: string, number, boolean, object, etc.","u":"Explains why some operations work on one value and fail on another."},{"c":"Database","n":"Database","p":"System for persistent storage/query of data.","u":"Users, jobs, invoices, settings, audit records."},{"c":"Database","n":"Deadlock","p":"Two operations wait on locks held by each other so neither can proceed.","u":"Databases detect/abort one transaction; retry and lock ordering may matter."},{"c":"Testing","n":"Debugging","p":"Finding the cause of a defect by evidence rather than by guessing.","u":"Reproduce, read the error, form one hypothesis, test it."},{"c":"Security","n":"Defence in Depth","p":"Layering independent protections so one failure is not fatal.","u":"Validation plus authorization plus rate limiting plus monitoring."},{"c":"Database","n":"Denormalization","p":"Intentionally duplicating/precomputing data to make reads simpler/faster.","u":"Analytics, caches, read-heavy views; adds consistency work."},{"c":"Language","n":"Dependency","p":"Code your project relies on.","u":"Frameworks, SDKs, libraries; also a supply-chain/security surface."},{"c":"Architecture","n":"Dependency injection","p":"Provide a component's dependencies from outside rather than constructing them internally.","u":"Testing and replacing services; frameworks often automate it."},{"c":"DevOps","n":"Deployment","p":"Making a version of the code the one real users are running.","u":"Test, build, stage, verify, promote."},{"c":"C++","n":"Dereference","p":"Reading the value a pointer points at, written *p.","u":"Dereferencing a null or dangling pointer is a crash or worse."},{"c":"Backend","n":"Deserialization","p":"Parsing transferred/stored data back into runtime values.","u":"Request bodies, cached data, message queues; treat untrusted input carefully."},{"c":"Architecture","n":"Distributed system","p":"Multiple networked computers cooperate to deliver one system.","u":"Adds partial failure, retries, latency, clock/consistency problems."},{"c":"Network","n":"DNS","p":"System that resolves domain names to records such as IP addresses.","u":"Custom domains, subdomains, email records, CDN routing."},{"c":"DevOps","n":"Docker","p":"The most common tool for building and running containers.","u":"A Dockerfile describes the image; the image runs anywhere."},{"c":"Frontend","n":"Document","p":"The whole HTML page, and the tree the browser builds from it.","u":"document.querySelector searches that tree."},{"c":"Frontend","n":"DOM","p":"The browser's object representation of the page.","u":"JavaScript reads/changes elements, attributes, text, focus, events."},{"c":"Network","n":"Domain name","p":"Human-readable name such as example.com.","u":"Web addresses, email, DNS configuration."},{"c":"Language","n":"Dynamic typing","p":"Types are associated with runtime values rather than fixed solely at declarations.","u":"JavaScript, Python; still possible to use type hints/checkers."},{"c":"Testing","n":"Edge Case","p":"An input at the boundary: zero, empty, negative, one, or enormous.","u":"Where most bugs actually live."},{"c":"Frontend","n":"Effect","p":"Logic that synchronizes a component with something outside pure rendering.","u":"Subscriptions, network calls, timers, browser APIs; React terminology is common."},{"c":"Core","n":"Element","p":"One item in an array or list, or one node in an HTML document.","u":"Context decides which meaning applies."},{"c":"Language","n":"Encapsulation","p":"Hide internal details behind a smaller public interface.","u":"Makes callers depend on behavior rather than implementation details."},{"c":"Security","n":"Encryption","p":"Reversible transformation using a key so authorized parties can recover plaintext.","u":"Data in transit/at rest; different from hashing."},{"c":"Testing","n":"End-to-end test","p":"Exercises the system from a user-level boundary through major layers.","u":"Browser workflows and critical journeys."},{"c":"DevOps","n":"Environment","p":"A configured place where software runs: local, test, staging, production.","u":"Different data, secrets, URLs, infrastructure."},{"c":"DevOps","n":"Environment variable","p":"Key/value configuration supplied outside source code to a process/build.","u":"DB URLs, API keys, feature config; not magically secret if exposed to browser builds."},{"c":"Core","n":"Equality","p":"Whether two values count as the same, which may mean identical content or the identical object.","u":"Java == compares identity for objects; .equals() compares content."},{"c":"Core","n":"Error Handling","p":"Deciding in advance what a program does when something fails.","u":"try/catch, guard clauses, and sensible fallbacks."},{"c":"Frontend","n":"Event","p":"A browser/runtime notification that something happened.","u":"click, input, submit, keydown, load, message."},{"c":"Frontend","n":"Event bubbling","p":"An event can travel from a target up through ancestor elements.","u":"Delegated handlers and surprising double-handling bugs."},{"c":"Frontend","n":"Event Listener","p":"A function registered to run when a particular event happens on an element.","u":"addEventListener(\"click\", handler)."},{"c":"Language","n":"Event loop","p":"The runtime mechanism that schedules queued asynchronous callbacks/jobs around the main execution stack.","u":"Explains why JS can handle many I/O operations without one thread per request."},{"c":"Architecture","n":"Event-driven architecture","p":"Components react to published events rather than direct synchronous calls for every workflow.","u":"Queues, pub/sub, integrations; adds ordering/idempotency/observability concerns."},{"c":"Core","n":"Exception","p":"An object representing a failure, thrown up the call stack until something catches it.","u":"Missing files, bad input, network drops."},{"c":"Database","n":"EXPLAIN","p":"Database tool showing how a query is planned/executed.","u":"Diagnosing scans, indexes, joins, slow queries."},{"c":"Backend","n":"Exponential backoff","p":"Retry delays increase after each failure, often with random jitter.","u":"Avoid hammering an unhealthy dependency."},{"c":"Core","n":"Expression","p":"Code that evaluates to a value.","u":"Conditionals, assignments, function arguments, return values."},{"c":"DevOps","n":"Feature flag","p":"Runtime switch controlling whether behavior is enabled for users/environments.","u":"Gradual rollout and decoupling deploy from release; flags need cleanup."},{"c":"Git","n":"Fetch","p":"Download remote refs/objects without automatically integrating into current work.","u":"Safely inspect what changed upstream."},{"c":"Frontend","n":"Filter","p":"Keeping only the items in a list that pass a test.","u":"Producing a shorter list without changing any item."},{"c":"Core","n":"First-class Function","p":"A function that can be stored in a variable, passed as an argument, and returned.","u":"The basis of callbacks, event handlers and list transformations."},{"c":"Testing","n":"Fixture","p":"Known setup data/environment used by tests.","u":"Seed users, records, files, request payloads."},{"c":"Frontend","n":"Flexbox","p":"One-dimensional CSS layout along a row or column.","u":"Toolbars, nav bars and centring."},{"c":"Database","n":"Foreign key","p":"Constraint linking a value to a row in another table.","u":"job.user_id references users.id."},{"c":"Frontend","n":"Form","p":"A group of inputs collected and submitted together.","u":"Every input needs a label and a name."},{"c":"Database","n":"Full Table Scan","p":"Reading every row because no usable index exists.","u":"Fine on small tables, ruinous on large ones."},{"c":"Core","n":"Function","p":"A named/reusable unit of behavior that can take inputs and produce outputs/side effects.","u":"Every layer of an application."},{"c":"Core","n":"Garbage collection","p":"Runtime automatically identifies unreachable memory and reclaims it.","u":"JavaScript, Python, Java; memory can still leak if you keep references forever."},{"c":"Language","n":"Generic","p":"A type/function defined to work with multiple types while preserving constraints.","u":"Reusable typed data structures and APIs."},{"c":"Language","n":"Generics","p":"Writing code that works with a type supplied later, checked at compile time.","u":"ArrayList<String> and vector<int>."},{"c":"Git","n":"Git","p":"A distributed version control system recording every change as a snapshot.","u":"Branching, history, and collaboration without overwriting each other."},{"c":"Database","n":"GROUP BY","p":"The SQL clause that buckets rows so aggregates produce one result per bucket.","u":"Revenue per product, orders per customer."},{"c":"Core","n":"Guard Clause","p":"An early return that handles the invalid case first, before the main logic.","u":"Keeps the happy path unindented and readable."},{"c":"AI Coding","n":"Hallucination (coding)","p":"AI confidently invents APIs, files, behavior, or causes that are not actually present.","u":"Verify against code, docs, tests, and runtime evidence."},{"c":"Backend","n":"Handler","p":"The function that produces a response for a particular route.","u":"Registered against a method and path."},{"c":"Backend","n":"Handler / controller","p":"Code invoked to handle a matched request/action.","u":"Parses inputs, calls services/business logic, returns response."},{"c":"Security","n":"Hash","p":"One-way-ish deterministic function producing a fixed-size digest.","u":"Password storage uses specialized password hashing, file integrity, cache keys."},{"c":"Architecture","n":"Hash Table","p":"A structure mapping keys to values with near-instant lookup.","u":"The engine behind Map, dict and object property access."},{"c":"Security","n":"Hashing","p":"Turning input into a fixed-size value that cannot be reversed.","u":"Passwords are stored as slow salted hashes, never as text."},{"c":"Database","n":"HAVING","p":"The SQL clause that filters groups after aggregation.","u":"WHERE cannot do this, because the totals do not exist yet."},{"c":"Network","n":"Header","p":"Metadata attached to HTTP requests/responses.","u":"Content type, auth, caching, cookies, CORS, tracing."},{"c":"C++","n":"Header File","p":"A file holding declarations (.h or .hpp) so several source files can agree on what exists.","u":"Included with #include so the compiler knows a function's shape before it sees the body."},{"c":"Frontend","n":"Heading","p":"An h1 to h6 element defining the document outline.","u":"One h1 per page, descending in order without skipping."},{"c":"DevOps","n":"Health check","p":"Probe that reports whether a service can accept useful work.","u":"Load balancers, orchestration, monitoring."},{"c":"Core","n":"Heap","p":"A simplified name for memory used for dynamically allocated objects/data.","u":"Useful mental model for object lifetime and memory leaks; exact runtime implementation varies."},{"c":"Architecture","n":"Horizontal scaling","p":"Add more instances/machines to share load.","u":"Web servers behind load balancer; state/session design matters."},{"c":"Backend","n":"Hosting","p":"Where a running application actually lives.","u":"Static CDN, serverless function, container or virtual machine."},{"c":"Frontend","n":"HTML","p":"The structure/meaning of web content.","u":"Buttons, forms, headings, links, tables, semantic document structure."},{"c":"Network","n":"HTTP","p":"Application protocol for request/response communication on the web.","u":"Browser/API traffic."},{"c":"Network","n":"HTTP method","p":"Verb describing request intent such as GET, POST, PUT, PATCH, DELETE.","u":"API routing and semantics."},{"c":"Network","n":"HTTPS","p":"HTTP protected by TLS encryption/authentication.","u":"Production web traffic; protects data in transit and verifies server identity."},{"c":"Frontend","n":"Hydration","p":"Client JavaScript attaches behavior/state to server-rendered HTML.","u":"React/Next-like frameworks; mismatch errors when first client render disagrees."},{"c":"Frontend","n":"Hyperlink","p":"An anchor element that navigates to another resource.","u":"Link text should make sense read out of context."},{"c":"Testing","n":"Hypothesis","p":"A single specific guess about the cause of a bug, stated so it can be tested.","u":"Change one thing at a time or you learn nothing."},{"c":"Backend","n":"Idempotency","p":"Repeating the same operation produces no additional unintended effect.","u":"Payment/webhook retries, job creation, resilient APIs."},{"c":"Security","n":"IDOR","p":"Insecure Direct Object Reference: reading someone else's record by changing an id.","u":"Prevented by checking ownership, not just login."},{"c":"DevOps","n":"Image","p":"The built, immutable package a container is started from.","u":"Built once, run many times."},{"c":"Core","n":"Immutability","p":"Treating existing values as unchanged and creating new values for updates.","u":"Predictable state updates, functional patterns, easier change detection."},{"c":"Database","n":"Index","p":"Additional data structure that speeds selected lookups/orderings at the cost of storage/write work.","u":"Frequent WHERE/JOIN/ORDER BY patterns; not “make every column indexed.”"},{"c":"Core","n":"Infinite Loop","p":"A loop whose condition never becomes false, so the program never continues.","u":"Almost always means the variable in the condition is never updated."},{"c":"Language","n":"Inheritance","p":"A type derives behavior/data from another type.","u":"Frameworks and OO designs; composition is often simpler when relationships are not truly “is-a”."},{"c":"Security","n":"Injection","p":"Untrusted input changes the meaning of a command/query rather than remaining data.","u":"SQL/OS/template injection; parameterization and safe APIs matter."},{"c":"Database","n":"Inner Join","p":"A join keeping only rows that matched on both sides.","u":"Silently drops unmatched rows, which hides them from counts."},{"c":"Frontend","n":"Input","p":"A control a user types into or selects from.","u":"Its type attribute drives validation and the mobile keyboard."},{"c":"Language","n":"Instance","p":"A concrete object created from a class or type.","u":"user = new User(...) is one instance."},{"c":"Core","n":"Integer","p":"A whole number with no fractional part.","u":"Counts, indexes and ids. Integer division truncates."},{"c":"Testing","n":"Integration test","p":"Tests multiple real components/boundaries working together.","u":"API + database, service + provider adapter."},{"c":"Java","n":"Interface","p":"A contract listing method signatures a class promises to provide.","u":"Lets unrelated classes be used interchangeably."},{"c":"Language","n":"Interface / protocol","p":"A contract describing capabilities/shape without prescribing one implementation.","u":"TypeScript interfaces, Java interfaces, Python protocols, API abstractions."},{"c":"Language","n":"Interpreter","p":"Executes code through a runtime rather than ahead-of-time native compilation in the simplest mental model.","u":"Python/JavaScript learning model; real engines often combine techniques."},{"c":"Network","n":"IP address","p":"A network address used to route traffic to a host/interface.","u":"DNS ultimately resolves names toward routable network destinations."},{"c":"Database","n":"Isolation level","p":"Rules for how concurrent transactions can observe each other's changes.","u":"Race conditions and correctness under concurrent writes."},{"c":"Core","n":"Iteration","p":"One pass through a loop, or the act of repeating a block of work.","u":"Each iteration usually changes something that eventually stops the loop."},{"c":"Database","n":"JOIN","p":"Combines related rows from multiple tables based on a condition.","u":"Fetch jobs with customer/owner data."},{"c":"Backend","n":"JSON","p":"Text format for structured values using objects, arrays, strings, numbers, booleans, null.","u":"Common HTTP API payload format."},{"c":"Java","n":"JVM","p":"The Java Virtual Machine, which runs compiled bytecode on any supported platform.","u":"It is why one build runs on Windows, Linux and macOS."},{"c":"Security","n":"JWT","p":"Signed token format containing claims.","u":"Auth systems; signing proves integrity, not secrecy unless separately encrypted."},{"c":"Network","n":"Latency","p":"Time delay for an operation/request.","u":"User-perceived speed and network/service performance."},{"c":"DevOps","n":"Layer","p":"One cached step in a container image build.","u":"Order the Dockerfile so rarely-changing steps come first."},{"c":"Architecture","n":"Layered architecture","p":"Separate responsibilities into layers such as UI, application/service, domain, persistence.","u":"Reduces tangling when boundaries stay meaningful."},{"c":"Frontend","n":"Layout","p":"How elements are positioned and sized relative to each other.","u":"Flexbox for one axis, Grid for two."},{"c":"Frontend","n":"Lazy loading","p":"Delay loading code/data/assets until needed.","u":"Route splitting, images, heavy components."},{"c":"Security","n":"Least privilege","p":"Give each user/service credential only the permissions it needs.","u":"DB accounts, cloud roles, GitHub tokens, service-to-service auth."},{"c":"Database","n":"Left Join","p":"A join keeping every row from the left table, with nulls where the right had no match.","u":"Customers who have not ordered yet still appear."},{"c":"Language","n":"List","p":"An ordered collection that allows duplicates and is reached by position.","u":"ArrayList in Java, vector in C++, array in JavaScript."},{"c":"Network","n":"Load balancer","p":"Distributes traffic across multiple app instances.","u":"Horizontal scaling and failover."},{"c":"Frontend","n":"LocalStorage","p":"Browser key/value storage that persists across tabs/restarts for an origin.","u":"Preferences/simple client data; not a safe place for secrets."},{"c":"Database","n":"Lock","p":"Mechanism preventing conflicting concurrent access/changes to data/resources.","u":"Transactions, deadlocks, long-running writes."},{"c":"DevOps","n":"Log","p":"Timestamped event/context emitted by software.","u":"Debugging, audit trails, operations; structured logs scale better than random strings."},{"c":"DevOps","n":"Logging","p":"Recording what happened, with enough context to reconstruct it later.","u":"Structured logs are searchable; free text is not."},{"c":"Core","n":"Loop","p":"Repeatedly executes a block while iterating or until a condition changes.","u":"Processing lists, retries, polling, transformations."},{"c":"Core","n":"Map","p":"A key→value collection optimized for lookup by key.","u":"Caches, indexes in memory, grouping records."},{"c":"Frontend","n":"Margin","p":"Space outside an element, pushing neighbours away.","u":"Vertical margins between siblings collapse into the larger one."},{"c":"Java","n":"Maven","p":"A build and dependency tool for Java projects, configured with pom.xml.","u":"Fetches libraries and produces a jar."},{"c":"Frontend","n":"Media Query","p":"A CSS block that only applies at certain screen sizes or conditions.","u":"The mechanism behind responsive layouts."},{"c":"Core","n":"Memory","p":"The storage a running program uses to hold its values.","u":"Split into the fast automatic stack and the flexible heap."},{"c":"Core","n":"Memory leak","p":"Memory remains reachable/allocated even though the program no longer needs it.","u":"Long-running servers, event listeners, caches, large browser apps."},{"c":"Git","n":"Merge","p":"Combines histories/changes from branches.","u":"Pull requests and integrating work."},{"c":"Git","n":"Merge conflict","p":"Git cannot automatically decide how overlapping changes should combine.","u":"You choose the intended final content, then mark resolved."},{"c":"Core","n":"Method","p":"A function that belongs to a class or object and can use its data.","u":"Called with dot notation: account.deposit(50)."},{"c":"DevOps","n":"Metric","p":"Numeric measurement tracked over time.","u":"Request rate, error rate, latency, CPU, queue depth."},{"c":"DevOps","n":"Metrics","p":"Numeric measurements collected over time.","u":"Counts, durations and rates, usually viewed as percentiles."},{"c":"Architecture","n":"Microservice","p":"Independently deployable service around a bounded responsibility.","u":"Can help organizational/scaling boundaries but adds network/ops/distributed-systems complexity."},{"c":"Backend","n":"Middleware","p":"Code that runs in a request pipeline before/after the main handler.","u":"Auth, logging, JSON parsing, rate limiting, CORS."},{"c":"Database","n":"Migration","p":"Versioned change to database schema/data structure.","u":"Add columns/tables/indexes safely across environments."},{"c":"Frontend","n":"Mobile First","p":"Designing for the smallest screen first and adding complexity upward.","u":"Usually produces simpler CSS than the reverse."},{"c":"Testing","n":"Mock","p":"Test replacement that imitates a dependency in a controlled way.","u":"External APIs/time/email; overmocking can make tests pass while integration is broken."},{"c":"Language","n":"Module","p":"A file/unit that exports functionality and imports dependencies.","u":"Organizing codebases and defining boundaries."},{"c":"DevOps","n":"Monitoring","p":"Collecting signals about a running system so you notice problems.","u":"Error rate, latency, throughput and saturation."},{"c":"Architecture","n":"Monolith","p":"Application deployed as one main unit/process boundary even if internally modular.","u":"Often simplest starting architecture for small teams/products."},{"c":"Core","n":"Mutation","p":"Changing an existing object/array rather than producing a new value.","u":"State management and bugs caused by shared references."},{"c":"Architecture","n":"MVC","p":"Model-View-Controller family of patterns separating data/domain, presentation, and input/control responsibilities.","u":"Many web frameworks; exact meaning varies."},{"c":"Database","n":"N+1 query","p":"Performance bug where one query loads a list and then one extra query runs per item.","u":"APIs/ORMs returning related data."},{"c":"Core","n":"Nested Loop","p":"A loop inside another loop, so the inner one runs fully on each outer pass.","u":"Grids, tables and comparison-based sorts."},{"c":"Frontend","n":"Node","p":"Any single point in the DOM tree: an element, a piece of text, or a comment.","u":"Elements are the nodes you usually work with."},{"c":"Database","n":"Normalization","p":"Structuring relational data to reduce duplication/update anomalies.","u":"Schema design; practical designs may denormalize deliberately for performance/read models."},{"c":"Database","n":"NoSQL","p":"Broad family of non-relational database models such as document, key-value, wide-column, graph.","u":"Useful when access patterns/model fit them; not automatically more scalable/simple."},{"c":"Database","n":"NOT NULL","p":"Constraint requiring a column value.","u":"Protects required data at the storage layer."},{"c":"Core","n":"Null","p":"An explicit “no value” marker.","u":"Database fields, optional relationships, intentionally empty state."},{"c":"Core","n":"Number","p":"Numeric data used for arithmetic, measurements, counts, money-like values with caveats.","u":"Calculations, pagination, timestamps, metrics."},{"c":"Core","n":"Object","p":"A value that bundles named data, and often behaviour, into one unit.","u":"A user, an order, a DOM element."},{"c":"Core","n":"Object / dictionary","p":"A collection of named properties/keys and values.","u":"Users, jobs, config, JSON request bodies."},{"c":"DevOps","n":"Observability","p":"Ability to understand internal system state from outputs such as logs, metrics, traces.","u":"Production debugging and reliability."},{"c":"Core","n":"Off-by-one","p":"Looping one step too far or stopping one step short, usually from <= instead of <.","u":"The most common logic error in every language."},{"c":"Core","n":"Operator","p":"A symbol/keyword that combines or transforms values.","u":"Math, comparisons, boolean logic, assignment."},{"c":"Network","n":"Origin","p":"Scheme + host + port used by browser security rules.","u":"CORS and browser isolation."},{"c":"Database","n":"ORM","p":"Library mapping application objects/functions to database queries.","u":"Prisma, SQLAlchemy, Django ORM, Hibernate; convenient but still worth knowing SQL."},{"c":"Core","n":"Overloading","p":"Several functions sharing one name but taking different parameter types or counts.","u":"The compiler picks by the arguments you pass."},{"c":"Core","n":"Override","p":"Replacing an inherited method with a new version in a subclass.","u":"The subclass version runs even through a parent-typed reference."},{"c":"Language","n":"Package","p":"A distributable collection of modules/code plus metadata.","u":"npm/PyPI dependencies and your own libraries."},{"c":"Language","n":"Package manager","p":"Tool that installs/resolves/version-controls project dependencies.","u":"npm, pnpm, yarn, pip, uv, Cargo."},{"c":"Frontend","n":"Padding","p":"Space inside an element, between its content and its border.","u":"Gives text room to breathe inside a card."},{"c":"Language","n":"Parallelism","p":"Multiple tasks literally executing at the same time on multiple cores/machines.","u":"CPU-bound work, worker pools, distributed processing."},{"c":"Core","n":"Parameter","p":"A named input in a function definition.","u":"Defines what a function expects."},{"c":"Security","n":"Parameterized Query","p":"Sending SQL and its values separately so input can never become code.","u":"The complete fix for SQL injection."},{"c":"Language","n":"Parser","p":"Software that turns source text into a structured representation.","u":"Compilers, interpreters, linters, formatters."},{"c":"Core","n":"Pass by Value","p":"Copying an argument into a function so changes inside do not affect the caller.","u":"The default in C++, Java and JavaScript for primitives."},{"c":"Network","n":"Path parameter","p":"Dynamic part of URL path identifying a resource/value.","u":"/users/123 where 123 is a parameter."},{"c":"Database","n":"Performance","p":"How fast a query or system runs as data and traffic grow.","u":"Usually fixed with an index, not with faster hardware."},{"c":"Backend","n":"Pipeline","p":"An ordered chain of steps a request or build passes through.","u":"Any step can stop it and return early."},{"c":"Core","n":"Pointer","p":"A value holding the memory address of something else.","u":"Central to C and C++; hidden behind references elsewhere."},{"c":"Backend","n":"Polling","p":"Client repeatedly asks whether something changed.","u":"Simple real-time-ish updates when push/websocket is unnecessary."},{"c":"Language","n":"Polymorphism","p":"Different implementations can be used through the same interface/contract.","u":"Swappable payment providers, storage backends, test doubles."},{"c":"Backend","n":"Port","p":"A numbered logical endpoint a network service listens on.","u":"localhost:3000, PostgreSQL 5432, HTTPS usually 443."},{"c":"Core","n":"Portfolio","p":"A small set of finished, deployed projects you can show and explain.","u":"Two working things beat ten unfinished ones."},{"c":"Backend","n":"POST","p":"The HTTP method for sending data that creates or changes something.","u":"Unlike GET, it is not safe to repeat blindly."},{"c":"Core","n":"Practice","p":"Deliberate repetition of a skill just past the edge of what you can already do.","u":"Rebuilding a project from a blank file rather than following along."},{"c":"Network","n":"Preflight","p":"Browser OPTIONS request checking CORS permission before certain cross-origin requests.","u":"Why your API sees OPTIONS before POST/PATCH."},{"c":"C++","n":"Preprocessor","p":"A pass that runs before compilation, handling #include, #define and conditional blocks.","u":"It is textual substitution, which is why macro bugs look so strange."},{"c":"Database","n":"Primary key","p":"Column(s) uniquely identifying each row.","u":"ID lookups and relationships."},{"c":"Core","n":"Primitive","p":"A raw built-in value type that is not an object.","u":"int, double, boolean and char in Java."},{"c":"Language","n":"Process","p":"A running program with its own operating-system resources/address space.","u":"Backend servers, workers, databases, local dev servers."},{"c":"Core","n":"Project","p":"A piece of work you finish end to end, rather than an exercise you follow.","u":"The gap between recognising code and writing it."},{"c":"Language","n":"Promise","p":"A JavaScript object representing a future completion or failure.","u":"fetch, async APIs, parallel async work."},{"c":"Core","n":"Property","p":"A named piece of data attached to an object.","u":"user.name, order.qty."},{"c":"Frontend","n":"Props","p":"Inputs passed from a parent component to a child in component frameworks.","u":"Configure child behavior/data; treat as owned by the parent."},{"c":"Network","n":"Proxy","p":"Server that forwards requests to another server.","u":"Dev proxies, reverse proxies, gateways, CDNs."},{"c":"Architecture","n":"Pub/sub","p":"Publishers emit messages to a topic; subscribers receive them without direct coupling.","u":"Notifications, analytics, integration events."},{"c":"Git","n":"Pull","p":"Typically fetch remote changes then integrate them into the current branch.","u":"Updating local branch; understand whether your tooling merges/rebases."},{"c":"Git","n":"Pull request","p":"Hosting-platform workflow to review/discuss/test proposed changes before merge.","u":"GitHub collaboration and automated checks."},{"c":"Git","n":"Push","p":"Send local commits/refs to a remote.","u":"Publishing your branch."},{"c":"Database","n":"Query","p":"A request to read or change database data.","u":"SELECT, INSERT, UPDATE, DELETE."},{"c":"Database","n":"Query Plan","p":"The database's chosen strategy for running a query, shown by EXPLAIN.","u":"Tells you whether your index was actually used."},{"c":"Network","n":"Query string","p":"Key/value parameters after ? in a URL.","u":"Filtering, pagination, search, optional request parameters."},{"c":"Backend","n":"Queue","p":"Buffer of jobs/messages waiting for consumers to process them.","u":"Reliability, retries, smoothing bursts."},{"c":"C++","n":"RAII","p":"Resource Acquisition Is Initialization: an object grabs a resource on construction and releases it on destruction.","u":"It is why vector and string clean up after themselves with no delete."},{"c":"Backend","n":"Rate Limit","p":"A cap on how many requests a caller may make in a period.","u":"Protects against abuse, runaway loops and brute-force attempts."},{"c":"Backend","n":"Rate limiting","p":"Restrict how many requests/actions a client can perform in a period.","u":"Abuse prevention, protecting expensive APIs, quotas."},{"c":"Frontend","n":"Re-render","p":"A component renders again because relevant state/inputs changed.","u":"Normal behavior until expensive/uncontrolled; profile before optimizing."},{"c":"Git","n":"Rebase","p":"Replays commits onto a different base to rewrite/linearize history.","u":"Keeping a feature branch current; powerful, avoid casually rebasing shared published history."},{"c":"Core","n":"Recursion","p":"A function solves a problem by calling itself on a smaller/subproblem.","u":"Trees, nested structures, graph traversal; can overflow the call stack if unbounded."},{"c":"Frontend","n":"Reduce","p":"Collapsing a whole list into a single value.","u":"Totals, averages, and building one object from many."},{"c":"Architecture","n":"Refactor","p":"Change internal code structure without intentionally changing external behavior.","u":"Improve readability/design after tests provide safety."},{"c":"Core","n":"Reference","p":"A value that points to an object rather than containing a separate copy of the whole object.","u":"Explains why two variables can observe the same mutated object."},{"c":"Testing","n":"Regression test","p":"Test added to prove a previously found bug stays fixed.","u":"Turn production mistakes into permanent automated knowledge."},{"c":"Database","n":"Relation","p":"A table, and by extension the links between tables.","u":"The word behind 'relational database'."},{"c":"Database","n":"Relational database","p":"Stores structured tables related through keys and queried with relational operations/SQL.","u":"PostgreSQL, MySQL, SQLite."},{"c":"Git","n":"Remote","p":"Named external Git repository location.","u":"origin usually points to GitHub/GitLab host."},{"c":"Frontend","n":"Render","p":"Turn current data/state into visible UI output.","u":"Framework rendering cycles and performance debugging."},{"c":"Database","n":"Reporting","p":"Summarising stored data into figures people act on.","u":"Almost entirely GROUP BY and aggregate functions."},{"c":"Git","n":"Repository","p":"Git-tracked project history and files.","u":"Your local project and GitHub remote."},{"c":"AI Coding","n":"Repository map","p":"Short explanation of important folders, entry points, data flow, scripts, and deployment.","u":"Gives humans/AI a mental model before edits."},{"c":"Network","n":"Request","p":"A message a client sends asking a server to do or return something.","u":"Method, path, headers and sometimes a body."},{"c":"Network","n":"Request body","p":"Payload sent with a request.","u":"JSON forms, uploads, commands."},{"c":"Git","n":"Reset","p":"Moves branch/index/working state depending on mode.","u":"Powerful local history manipulation; understand --soft/--mixed/--hard before use."},{"c":"Network","n":"Response","p":"The message a server sends back.","u":"Status code, headers and usually a body."},{"c":"Frontend","n":"Responsive Design","p":"Building one layout that adapts to any screen size.","u":"Fluid widths, media queries, and auto-fit grids."},{"c":"Backend","n":"REST","p":"A common HTTP API style centered on resources and standard HTTP semantics.","u":"CRUD-like web APIs; not the only valid API style."},{"c":"Backend","n":"Retry","p":"Attempt a failed operation again under controlled rules.","u":"Transient network/service failures; dangerous for non-idempotent side effects."},{"c":"Core","n":"Return value","p":"The value a function sends back to its caller.","u":"Pipelines of transformations and API/service functions."},{"c":"Network","n":"Reverse proxy","p":"Front server that receives user traffic and forwards it to internal application services.","u":"TLS termination, routing, load balancing, Nginx/Traefik/cloud gateways."},{"c":"Git","n":"Revert","p":"Create a new commit that undoes an earlier commit's changes.","u":"Safer for shared history than deleting published commits."},{"c":"DevOps","n":"Rollback","p":"Return production to a previous known-good release/config.","u":"Part of safe deployment planning."},{"c":"Backend","n":"Route","p":"A mapping from request method/path to handler code.","u":"GET /users/:id, POST /jobs."},{"c":"Frontend","n":"Router (frontend)","p":"Maps browser URLs to UI views/components.","u":"Navigation, nested pages, route parameters."},{"c":"Database","n":"Row / record","p":"One stored entity/entry in a table.","u":"One user or one job."},{"c":"Backend","n":"RPC","p":"Remote procedure call style where the client invokes named remote operations.","u":"Internal APIs, gRPC, tRPC-style systems, action-oriented endpoints."},{"c":"Language","n":"Runtime","p":"The environment actually executing your program.","u":"Browser JavaScript runtime, Node.js, Python interpreter, JVM, .NET runtime."},{"c":"Core","n":"Runtime Error","p":"A failure that only appears while the program is running, not when it is compiled.","u":"Dividing by zero, reading past an array, or using a null value."},{"c":"Security","n":"Salt","p":"Random data mixed into a password before hashing, unique per user.","u":"Stops one precomputed table from cracking every account."},{"c":"Security","n":"Sanitization","p":"Cleaning or escaping input so it cannot be interpreted as code.","u":"Escape at output, based on where the value is going."},{"c":"Backend","n":"Schema","p":"An explicit description of data structure and constraints.","u":"Database schema, JSON schema, validation schema, API contracts."},{"c":"Core","n":"Scope","p":"The region of code where a name is visible/accessible.","u":"Explains ReferenceError, variable shadowing, closures."},{"c":"DevOps","n":"Secret","p":"Sensitive credential/material that grants access or protects data.","u":"API keys, DB passwords, signing keys; keep out of repos/logs/client bundles."},{"c":"Database","n":"SELECT","p":"The SQL statement that reads rows.","u":"SELECT columns FROM table WHERE condition."},{"c":"Frontend","n":"Selector","p":"A pattern that picks out elements, used by both CSS and querySelector.","u":"#id, .class, nav a."},{"c":"Frontend","n":"Semantic HTML","p":"Choosing elements for their meaning rather than their default appearance.","u":"header, nav, main and article instead of a wall of divs."},{"c":"Language","n":"Semantic versioning","p":"Common MAJOR.MINOR.PATCH convention for communicating compatibility intent.","u":"Dependency upgrades and release versions; not a guarantee that every package follows it perfectly."},{"c":"Language","n":"Semantics","p":"What valid code actually means/does.","u":"Two syntactically valid snippets can have very different behavior."},{"c":"Frontend","n":"SEO","p":"Practices that help search engines understand and rank a page.","u":"Good headings, semantic markup, fast loading and real content."},{"c":"Backend","n":"Serialization","p":"Converting in-memory data into a transferable/storable representation.","u":"JSON encoding, database formats, messages."},{"c":"Backend","n":"Server","p":"A program/computer that listens for requests and provides responses/services.","u":"Backend APIs, static files, databases, proxies."},{"c":"Network","n":"Server Error","p":"A 5xx status meaning the server failed while handling a valid request.","u":"Check the server logs."},{"c":"Frontend","n":"Server-side rendering (SSR)","p":"Server produces HTML for a request before the browser hydrates/continues interaction.","u":"SEO, first render performance, modern frameworks."},{"c":"Backend","n":"Serverless","p":"Running code as functions that start on demand and stop when idle.","u":"Cheap when quiet, with cold starts as the trade-off."},{"c":"Backend","n":"Service layer","p":"A code boundary that groups application/business operations away from transport/UI details.","u":"Keeps route handlers thin and logic reusable/testable."},{"c":"Frontend","n":"Service worker","p":"A browser worker that can intercept requests and enable offline/cache/push behaviors.","u":"PWAs, offline strategies, cache management."},{"c":"Security","n":"Session","p":"Server-recognized login state associated with a client, often via a cookie identifier.","u":"Web authentication."},{"c":"Core","n":"Set","p":"A collection designed around unique values.","u":"Fast membership checks and removing duplicates."},{"c":"Core","n":"Shadowing","p":"An inner variable hiding an outer one with the same name.","u":"Often deliberate, occasionally the source of a confusing bug."},{"c":"Core","n":"Side effect","p":"A function changes something outside its returned value: DB write, log, network call, DOM change.","u":"Important for testing, retries, and understanding hidden behavior."},{"c":"C++","n":"Smart Pointer","p":"A pointer object that frees what it owns automatically (unique_ptr, shared_ptr).","u":"Modern C++ uses these instead of raw new and delete."},{"c":"Core","n":"Sorting","p":"Arranging items into order by some comparison rule.","u":"Use the standard library sort unless you are learning how it works."},{"c":"Frontend","n":"SPA","p":"Single-page application: navigation/UI updates mostly happen without full browser page reloads.","u":"Dashboards, web apps, client routing."},{"c":"AI Coding","n":"Spec-first change","p":"Describe expected behavior, boundaries, non-goals, and acceptance checks before asking for edits.","u":"Prevents agents from solving the wrong problem beautifully."},{"c":"Frontend","n":"Specificity","p":"The ranking that decides which CSS rule wins a conflict.","u":"id beats class beats element; ties go to whichever comes last."},{"c":"Database","n":"SQL","p":"Language for querying/manipulating relational databases.","u":"PostgreSQL/MySQL/SQLite work."},{"c":"Security","n":"SQL Injection","p":"Attacker input becoming part of a SQL command rather than staying a value.","u":"Prevented completely by parameterised queries."},{"c":"Backend","n":"SSE","p":"Server-Sent Events: server pushes a stream of events over an HTTP response to the client.","u":"One-way live updates simpler than full WebSockets in some cases."},{"c":"Core","n":"Stack","p":"The region of memory holding local variables and the record of active function calls.","u":"Freed automatically when a function returns."},{"c":"Core","n":"Stack overflow","p":"Too many nested calls exhaust the call stack.","u":"Usually runaway recursion or deeply recursive processing."},{"c":"Core","n":"Stack Trace","p":"The list of function calls that were active when an error happened, printed innermost first.","u":"Read it bottom-up to find where the chain started."},{"c":"DevOps","n":"Staging","p":"An environment resembling production, used to verify a build before release.","u":"Only useful if it is genuinely similar."},{"c":"Git","n":"Staging Area","p":"The set of changes selected for the next commit.","u":"git add moves work here; git commit records it."},{"c":"Git","n":"Staging area / index","p":"Git's selected snapshot for the next commit.","u":"git add chooses which changes enter the next commit."},{"c":"Core","n":"Standard Input","p":"The default channel a program reads from, usually the keyboard or piped data.","u":"cin in C++, Scanner in Java, stdin on the command line."},{"c":"Core","n":"Standard Library","p":"The set of tools shipped with a language, needing no installation.","u":"Learning it well removes most reasons to add a dependency."},{"c":"Git","n":"Stash","p":"Temporarily save uncommitted changes away from working tree.","u":"Switch context without making a real commit."},{"c":"Frontend","n":"State","p":"The data a program currently holds, from which the display is derived.","u":"Change state, then re-render from it."},{"c":"Frontend","n":"State (UI)","p":"Data whose change can cause the interface to render differently.","u":"Form values, selected tab, fetched records, loading status."},{"c":"Backend","n":"Stateless","p":"Handling each request without relying on memory of previous ones.","u":"Lets any instance serve any request, which is what makes scaling easy."},{"c":"Architecture","n":"Stateless service","p":"Any request can be handled without depending on hidden process-local session state from earlier requests.","u":"Easier horizontal scaling; persistent state lives in shared stores."},{"c":"Core","n":"Statement","p":"A complete instruction performed by the program.","u":"Variable declarations, returns, loops, conditionals."},{"c":"Core","n":"Static","p":"Belonging to the class itself rather than to any individual object.","u":"Called without creating an instance, like Math.max."},{"c":"Frontend","n":"Static site generation (SSG)","p":"HTML is generated ahead of user requests during build time.","u":"Docs, marketing pages, content sites."},{"c":"Language","n":"Static typing","p":"Types are checked before execution/build in the usual workflow.","u":"TypeScript, Java, Rust, C#."},{"c":"Network","n":"Status code","p":"Three-digit HTTP response category/result.","u":"2xx success, 3xx redirect, 4xx client/request issue, 5xx server-side failure."},{"c":"C++","n":"STL","p":"The Standard Template Library: vector, map, string, algorithms and iterators.","u":"Reach for it before writing your own container or sort."},{"c":"Core","n":"Stream","p":"A sequence of data read or written one piece at a time rather than all at once.","u":"cout, cin, file reads, network sockets."},{"c":"Core","n":"String","p":"Text data: names, IDs, messages, URLs, JSON text.","u":"Forms, APIs, logs, database columns, configuration."},{"c":"Core","n":"Substring","p":"A contiguous slice taken out of a string.","u":"Pulling a surname out of a full name."},{"c":"Language","n":"Synchronous","p":"The caller waits for an operation to finish before continuing.","u":"Normal function calls and blocking operations."},{"c":"Language","n":"Syntax","p":"The grammar rules that make code valid in a language.","u":"SyntaxError means the parser could not understand the written form."},{"c":"Database","n":"Table","p":"Named collection of rows with defined columns.","u":"users, jobs, invoices."},{"c":"Frontend","n":"Tag","p":"The angle-bracketed marker that opens or closes an HTML element.","u":"<p> opens, </p> closes."},{"c":"Architecture","n":"Technical debt","p":"Future cost created by shortcuts/design constraints that make later change harder.","u":"Not all debt is bad; invisible/unmanaged debt is risky."},{"c":"Testing","n":"Test coverage","p":"Measurement of which code lines/branches/etc. tests executed.","u":"A signal, not proof that behavior is meaningfully tested."},{"c":"Testing","n":"Testing","p":"Writing code that runs your code and checks the result.","u":"Catches the day something that used to work stops working."},{"c":"Language","n":"Thread","p":"An execution path inside a process that can share process memory with other threads.","u":"Concurrency, background work, CPU tasks; semantics vary by runtime."},{"c":"Security","n":"Threat model","p":"Structured thinking about assets, attackers, trust boundaries, abuse paths, mitigations.","u":"Security review before incidents."},{"c":"Network","n":"Throughput","p":"Amount of work/data handled per unit time.","u":"Capacity planning; different from how fast one request feels."},{"c":"Core","n":"Time Complexity","p":"How the work grows as input grows, written as Big O.","u":"O(n) doubles when input doubles; O(n^2) quadruples."},{"c":"Backend","n":"Timeout","p":"Maximum time you will wait before treating an operation as failed.","u":"Network, database, external services. Prevents waiting forever."},{"c":"Network","n":"TLS","p":"Cryptographic protocol providing encrypted/authenticated connections.","u":"HTTPS certificates and secure service connections."},{"c":"Security","n":"Token","p":"Data representing claims/credentials used to authenticate/authorize or identify operations.","u":"Access tokens, refresh tokens, API keys, CSRF tokens. Different tokens have different purposes."},{"c":"DevOps","n":"Trace","p":"Record of one request/workflow across services/spans.","u":"Distributed systems and latency breakdowns."},{"c":"Database","n":"Transaction","p":"Group of database operations committed or rolled back as one unit.","u":"Payments, inventory changes, multi-row business updates."},{"c":"Frontend","n":"Transpiler","p":"Transforms source code into another source-level form.","u":"TypeScript→JavaScript, modern syntax transformations."},{"c":"Frontend","n":"Tree shaking","p":"Build optimization that removes unused exported code when analysis permits.","u":"Reducing JavaScript bundle size."},{"c":"Core","n":"Truthy","p":"A value that behaves as true in a condition without being the boolean true.","u":"Rules differ per language, which is why explicit comparisons are safer."},{"c":"Architecture","n":"TTL","p":"Time-to-live: how long cached/data entries remain valid before expiration.","u":"Caches, DNS, tokens, temporary records."},{"c":"Backend","n":"Twelve-Factor","p":"A set of conventions for building portable, deployable services.","u":"Config in the environment, stateless processes, logs to stdout."},{"c":"Core","n":"Type Coercion","p":"Automatic conversion of a value from one type to another.","u":"5 + \"5\" giving \"55\" in JavaScript."},{"c":"Language","n":"Type inference","p":"Compiler/checker figures out a type from context without you writing it explicitly.","u":"TypeScript and many typed languages."},{"c":"Core","n":"Type Safety","p":"The degree to which a language stops you using a value as the wrong kind of thing.","u":"C++ and Java catch many of these at compile time; JavaScript does not."},{"c":"Language","n":"Type system","p":"Rules/tools for classifying values and allowed operations.","u":"Catches some mistakes before runtime and documents expectations."},{"c":"Core","n":"Undefined","p":"In JavaScript, a value usually meaning something was not assigned/provided/found.","u":"Missing object properties, arguments, variables, failed lookups."},{"c":"C++","n":"Undefined Behaviour","p":"Code the C++ standard places no requirements on, such as reading past an array end.","u":"It may work, crash, or corrupt data silently. It is the reason bounds matter."},{"c":"Database","n":"Unique constraint","p":"Database rule preventing duplicate values/combinations.","u":"Email uniqueness, external payment IDs, idempotency keys."},{"c":"Testing","n":"Unit test","p":"Tests a small unit of behavior with tight boundaries.","u":"Pure functions, validation rules, services."},{"c":"Network","n":"URL","p":"Structured address describing protocol, host, path, query, etc.","u":"API endpoints, browser navigation, assets."},{"c":"Backend","n":"Validation","p":"Check that input satisfies expected shape/rules before using it.","u":"API bodies, forms, config, webhook payloads."},{"c":"Core","n":"Value semantics","p":"Behavior where a value is copied/compared as its actual value rather than shared identity.","u":"Primitive values and some language-specific types."},{"c":"Core","n":"Variable","p":"A name your code uses to refer to a value.","u":"Everywhere: counts, user objects, configuration, temporary results."},{"c":"Core","n":"Vector","p":"A resizable array from the C++ standard library that knows its own size.","u":"Prefer it to a raw array in modern C++."},{"c":"Architecture","n":"Vertical scaling","p":"Give one machine/process more CPU/RAM/resources.","u":"Often simpler until hardware/cost limits."},{"c":"DevOps","n":"Volume","p":"Storage mounted into a container/process lifecycle separately from ephemeral container filesystem.","u":"Persistent database/files and local dev mounts."},{"c":"Backend","n":"Webhook","p":"One system sends an HTTP request to another when an event happens.","u":"Payments, GitHub events, email events, automation integrations."},{"c":"Backend","n":"WebSocket","p":"A long-lived two-way connection between client and server.","u":"Chats, live dashboards, collaborative apps."},{"c":"Database","n":"WHERE","p":"The SQL clause that filters rows before anything else happens.","u":"Runs before grouping; use HAVING to filter after."},{"c":"Backend","n":"Worker","p":"A process/thread/function consuming background jobs.","u":"Queue processing, CPU tasks."},{"c":"Git","n":"Working tree","p":"Current files as they exist on disk, including uncommitted edits.","u":"git status shows changes relative to index/HEAD."},{"c":"Security","n":"XSS","p":"Cross-site scripting: untrusted content executes as script in another user's browser context.","u":"Output encoding, safe DOM APIs, CSP, avoiding unsafe HTML injection."}];
